1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Optional;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Converts a raw telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
8	 * form: a leading '+' followed by 8 to 15 digits.
9	 *
10	 * <p>An explicit leading '+' and country code are kept; otherwise the default country code
11	 * {@code +61} is assumed and a single leading '0' is dropped from the national digits.
12	 * Spaces, dashes and brackets are stripped. So {@code "0412 345 678"} becomes
13	 * {@code "+61412345678"} and {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
14	 */
15	public final class E164PhoneNumber {
16	
17	    /** Country code assumed when the input does not carry an explicit '+' prefix. */
18	    private static final String DEFAULT_COUNTRY_CODE = "61";
19	
20	    /** Separators removed before parsing: spaces, dashes and brackets. */
21	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
22	
23	    /** A well-formed E.164 number: '+' then 8 to 15 digits. */
24	    private static final Pattern E164 = Pattern.compile("\\+[0-9]{8,15}");
25	
26	    private E164PhoneNumber() {
27	    }
28	
29	    /**
30	     * @param raw the caller-supplied telephone, in any common format
31	     * @return the E.164 string, or empty when {@code raw} cannot form a valid one
32	     */
33	    public static Optional<String> toE164(String raw) {
34	        if (raw == null) {
35	            return Optional.empty();
36	        }
37	        String trimmed = raw.trim();
38	        boolean explicitCountryCode = trimmed.startsWith("+");
39	        String cleaned = SEPARATORS.matcher(trimmed).replaceAll("");
40	        String digits;
41	        if (explicitCountryCode) {
42	            digits = cleaned.substring(1); // drop the '+', keep the country code
43	        }
44	        else {
45	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
46	            digits = DEFAULT_COUNTRY_CODE + national;
47	        }
48	        String candidate = "+" + digits;
49	        return E164.matcher(candidate).matches() ? Optional.of(candidate) : Optional.empty();
50	    }
51	}
