8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Shared household logic. An owner belongs to a household identified by their last name
13	 * and postal address, compared case-insensitively with collapsed whitespace. The
14	 * identifier is derived deterministically from those two fields, so every owner in the
15	 * same household resolves to the same stable value without any coordination.
16	 */
17	final class Households {
18	
19	    private Households() {
20	    }
21	
22	    /**
23	     * The existing owners that share a household (same last name and address) with the
24	     * given fields.
25	     */
26	    static List<Owner> membersOf(OwnerRepository ownerRepository, String lastName, String address) {
27	        String key = normalize(lastName);
28	        String addr = normalize(address);
29	        return ownerRepository.findByLastName(lastName).stream()
30	                .filter(owner -> normalize(owner.getLastName()).equals(key)
31	                        && normalize(owner.getAddress()).equals(addr))
32	                .toList();
33	    }
34	
35	    /**
36	     * The stable identifier shared by every owner at the given last name and address.
